/* ===========================
   Live region
   =========================== */
.live-region {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}

/* ===========================
   Toast notification
   =========================== */
.toast-container {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  max-width: 320px;
}

.toast {
  background: var(--color-text);
  color: #fff;
  padding: .875rem 1.125rem;
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: .625rem;
  box-shadow: var(--shadow-lg);
  animation: toastIn 200ms ease, toastOut 300ms ease 2.5s forwards;
}

.toast-icon { font-size: 1.125rem; flex-shrink: 0; }

@keyframes toastIn {
  from { opacity: 0; transform: translateX(1rem); }
  to   { opacity: 1; transform: translateX(0); }
}
@keyframes toastOut {
  from { opacity: 1; }
  to   { opacity: 0; pointer-events: none; }
}

/* ===========================
   Responsive
   =========================== */
@media (max-width: 1024px) {
  .editorial-grid {
    grid-template-columns: 1fr 1fr;
  }
  .editorial-card.editorial-featured { grid-row: span 1; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
}

@media (max-width: 768px) {
  .header-inner { grid-template-columns: auto 1fr auto; }
  .primary-nav { display: none; }
  .search-form { display: none; }
  .menu-toggle { display: flex; }

  .hero-inner { grid-template-columns: 1fr; min-height: auto; }
  .hero-visual { display: none; }
  .hero-badge { display: none; }

  .editorial-grid { grid-template-columns: 1fr; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 2rem; }

  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 480px) {
  .deal-card-media { width: 90px; }
  .footer-grid { grid-template-columns: 1fr; gap: 1.5rem; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .trust-list { flex-direction: column; align-items: flex-start; gap: .875rem; }
}

/* ===========================
   Reduced motion
   =========================== */
@media (prefers-reduced-motion: reduce) {
