  color: var(--color-text-inverse);
  text-align: center;
  padding: .5rem var(--gutter);
  font-size: .8125rem;
  letter-spacing: .02em;
}
.announcement-bar a {
  color: #fbbf24;
  font-weight: 600;
  text-decoration: underline;
}

/* ===========================
   Site header
   =========================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 1rem;
  height: 64px;
}

/* Logo */
.site-logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: 1.375rem;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--color-text);
  justify-self: start;
}
.site-logo:focus-visible { border-radius: var(--radius-sm); }
.logo-mark {
  width: 32px; height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: .9rem;
  font-weight: 900;
  flex-shrink: 0;
}

/* Primary nav */
.primary-nav { justify-self: center; }
.nav-list {
  display: flex;
  gap: .25rem;
}
.nav-list a {
  padding: .375rem .75rem;
  border-radius: var(--radius-sm);
  font-size: .9375rem;
  font-weight: 500;
  color: var(--color-text-muted);
  transition: color var(--transition), background var(--transition);
}
.nav-list a:hover,
.nav-list a[aria-current="page"] {
  color: var(--color-text);
  background: var(--color-surface-alt);
}
.nav-list a:focus-visible { outline-offset: 0; }

/* Header actions */
.header-actions {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: .25rem;
}

.icon-btn {
  width: 40px; height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
  color: var(--color-text-muted);
  transition: color var(--transition), background var(--transition);
  position: relative;
}
.icon-btn:hover { color: var(--color-text); background: var(--color-surface-alt); }

.cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  width: 17px; height: 17px;
  background: var(--color-accent);
  color: #fff;
  font-size: .65rem;
  font-weight: 700;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--color-surface);
}

/* Search form in header */
.search-form {
  display: flex;
  align-items: center;
  gap: .5rem;
  background: var(--color-surface-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  padding: .25rem .25rem .25rem .875rem;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.search-form:focus-within {
  border-color: var(--color-focus);
  box-shadow: 0 0 0 3px rgba(37,99,235,.15);
}
.search-form input {
  background: none;
  border: none;
  outline: none;
  font: inherit;
  font-size: .875rem;
  color: var(--color-text);
  width: 180px;
}
.search-form input::placeholder { color: var(--color-text-muted); }
.search-submit {
  width: 30px; height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-text);
  color: #fff;
  border-radius: var(--radius-pill);
  transition: background var(--transition);
  flex-shrink: 0;
}
.search-submit:hover { background: var(--color-accent); }

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  width: 40px; height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
  color: var(--color-text);
}

/* ===========================
   Mobile nav drawer
   =========================== */
.mobile-nav {
  display: none;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding: 1rem var(--gutter);
}
.mobile-nav.open { display: block; }
.mobile-nav-list {
  display: flex;
  flex-direction: column;
  gap: .25rem;
}
.mobile-nav-list a {
  display: block;
  padding: .625rem .75rem;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-text);
}
.mobile-nav-list a:hover { background: var(--color-surface-alt); }

/* ===========================
   Hero
   =========================== */
.hero {
  background: linear-gradient(135deg, #1a1a18 0%, #2d2b27 100%);
  color: var(--color-text-inverse);
  overflow: hidden;
  position: relative;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
  min-height: 520px;
  padding-block: 4rem;
}

.hero-content { position: relative; z-index: 1; }

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: var(--color-accent);
  color: #fff;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: .3rem .75rem;
  border-radius: var(--radius-pill);
  margin-bottom: 1.25rem;
}

.hero-title {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 800;
  letter-spacing: -.04em;
  line-height: 1.1;
  margin-bottom: 1rem;
}

.hero-title em {
  font-style: normal;
  color: #fbbf24;
}

.hero-desc {
  font-size: 1.0625rem;
  color: rgba(255,255,255,.75);
  max-width: 440px;
  margin-bottom: 2rem;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  gap: .75rem;
  flex-wrap: wrap;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .75rem 1.5rem;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 600;
  transition: background var(--transition), color var(--transition), box-shadow var(--transition), transform var(--transition);
  cursor: pointer;
}
.btn:active { transform: scale(.98); }

.btn-primary {
  background: var(--color-accent);
  color: #fff;
}
.btn-primary:hover { background: var(--color-accent-hover); }

.btn-outline {
  background: transparent;
  color: #fff;
  border: 2px solid rgba(255,255,255,.35);
}
.btn-outline:hover { border-color: #fff; background: rgba(255,255,255,.08); }

.btn-ghost {
  background: var(--color-surface-alt);
  color: var(--color-text);
}
.btn-ghost:hover { background: var(--color-border); }

/* Hero visual */
.hero-visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-img-wrap {
  width: 100%;
  max-width: 480px;
  aspect-ratio: 4/3;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: #2d2b27;
  position: relative;
}

.hero-img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  background: linear-gradient(135deg, #2d2b27 0%, #3d3a34 50%, #4a4640 100%);
}

.hero-product-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: .75rem;
  padding: 1.5rem;
  width: 100%;
  height: 100%;
}

.hero-card-mini {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: var(--radius-md);
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: .5rem;
}
.hero-card-mini-icon {
  width: 36px; height: 36px;
  background: rgba(255,255,255,.1);
  border-radius: var(--radius-sm);
}
.hero-card-mini-line {
  height: 8px;
  background: rgba(255,255,255,.15);
  border-radius: 4px;
}
.hero-card-mini-line.short { width: 60%; }
.hero-card-mini-price {
  font-size: .75rem;
  font-weight: 700;
  color: #fbbf24;
}

.hero-badge {
  position: absolute;
  bottom: -12px;
  right: -12px;
  background: var(--color-accent);
  color: #fff;
  border-radius: 50%;
  width: 88px; height: 88px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: .75rem;
  line-height: 1.2;
  text-align: center;
  box-shadow: var(--shadow-lg);
  border: 3px solid var(--color-bg);
}
.hero-badge span { font-size: 1.375rem; }

/* ===========================
   Category strip
   =========================== */
.category-strip {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding: 1.5rem 0;
}

.category-list {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: 2px;
  -webkit-overflow-scrolling: touch;
}
.category-list::-webkit-scrollbar { display: none; }

.category-item {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .5rem;
  cursor: pointer;
}

.category-item a {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .5rem;
  padding: .5rem .75rem;
  border-radius: var(--radius-md);
  transition: background var(--transition);
}
.category-item a:hover { background: var(--color-surface-alt); }

.category-icon {
  width: 56px; height: 56px;
  background: var(--color-surface-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  transition: background var(--transition);
}
.category-item a:hover .category-icon { background: var(--color-accent-light); }

.category-label {
  font-size: .8125rem;
  font-weight: 500;
  color: var(--color-text-muted);
  white-space: nowrap;
}

/* ===========================
   Sections (shared spacing)
   =========================== */
.section { padding-block: clamp(2rem, 5vw, 4rem); }

/* ===========================
   Product grid
   =========================== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.5rem;
}

/* Product card */
.product-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
}
.product-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.product-card-media {
  position: relative;
  aspect-ratio: 1;
  background: var(--color-surface-alt);
  overflow: hidden;
}

.product-card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 300ms ease;
}
.product-card:hover .product-card-img { transform: scale(1.04); }

/* Placeholder image */
.product-img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
}

.product-badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  padding: .2rem .6rem;
  border-radius: var(--radius-pill);
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.badge-new { background: var(--color-badge-new); color: #fff; }
.badge-sale { background: var(--color-accent); color: #fff; }
.badge-bestseller { background: #78350f; color: #fef3c7; }

.product-card-wishlist {
  position: absolute;
  top: .75rem;
  right: .75rem;
  width: 32px; height: 32px;
  background: var(--color-surface);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  box-shadow: var(--shadow-sm);
  transition: color var(--transition), background var(--transition);
}
.product-card-wishlist:hover { color: var(--color-accent); background: var(--color-accent-light); }
.product-card-wishlist[aria-pressed="true"] { color: var(--color-accent); }

.product-card-body {
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: .375rem;
  flex: 1;
}

.product-brand {
  font-size: .75rem;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: .05em;
}

.product-name {
  font-size: .9375rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--color-text);
}

.product-rating {
  display: flex;
  align-items: center;
  gap: .375rem;
}
.stars {
  display: flex;
  color: #f59e0b;
  font-size: .8125rem;
}
.rating-count {
  font-size: .75rem;
  color: var(--color-text-muted);
}

.product-price-row {
  display: flex;
  align-items: center;
  gap: .5rem;
  flex-wrap: wrap;
  margin-top: auto;
  padding-top: .25rem;
}
.price-current {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--color-text);
}
.price-original {
  font-size: .875rem;
  color: var(--color-text-muted);
  text-decoration: line-through;
}
.price-save {
  font-size: .75rem;
  font-weight: 600;
  color: var(--color-deal);
  background: var(--color-deal-bg);
  padding: .1rem .4rem;
  border-radius: var(--radius-pill);
}

.product-card-footer {
  padding: 0 1rem 1rem;
}

.btn-add-cart {
  width: 100%;
  justify-content: center;
  background: var(--color-text);
  color: #fff;
  padding: .625rem 1rem;
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition);
}
.btn-add-cart:hover { background: var(--color-accent); }
.btn-add-cart:active { transform: scale(.97); }

/* ===========================
   Deals section
   =========================== */
.deals-section {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.deals-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 1.75rem;
}

.deals-title-group {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.deals-title-group h2 {
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -.02em;
}

.countdown {
  display: flex;
  align-items: center;
  gap: .375rem;
  background: var(--color-accent-light);
  border: 1px solid rgba(200,68,26,.2);
  border-radius: var(--radius-pill);
  padding: .3rem .875rem;
}

.countdown-label {
  font-size: .75rem;
  font-weight: 600;
  color: var(--color-accent);
  text-transform: uppercase;
  letter-spacing: .05em;
}

.countdown-timer {
  display: flex;
  align-items: center;
  gap: .125rem;
  font-size: .875rem;
  font-weight: 700;
  color: var(--color-accent);
  font-variant-numeric: tabular-nums;
}

.countdown-sep { opacity: .6; }

/* Deal card — horizontal layout */
.deal-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  gap: 0;
  transition: box-shadow var(--transition), transform var(--transition);
}
.deal-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.deal-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.25rem;
}

.deal-card-media {
  width: 120px;
  flex-shrink: 0;
  background: var(--color-surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}

.deal-card-body {
  padding: 1.125rem;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: .375rem;
}

.deal-card-name {
  font-size: .9375rem;
  font-weight: 600;
  line-height: 1.35;
}

.deal-card-original {
  font-size: .8125rem;
  color: var(--color-text-muted);
  text-decoration: line-through;
}

.deal-card-price {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--color-accent);
}

.deal-progress {
  display: flex;
  flex-direction: column;
  gap: .25rem;
  margin-top: auto;
}

.progress-bar {
  height: 6px;
  background: var(--color-border);
  border-radius: var(--radius-pill);
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: var(--color-deal);
  border-radius: var(--radius-pill);
  transition: width 1.2s ease;
}

.progress-label {
  font-size: .75rem;
  color: var(--color-text-muted);
}
.progress-label strong { color: var(--color-deal); }

/* ===========================
   Editorial section
   =========================== */
.editorial-section { background: var(--color-bg); }

.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.5rem;
}

.editorial-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
.editorial-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.editorial-card-media {
  aspect-ratio: 16/7;
  background: var(--color-surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}
.editorial-card:not(.editorial-featured) .editorial-card-media {
  aspect-ratio: 16/9;
}

.editorial-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: flex-end;
  padding: 1.5rem;
  position: relative;
}

.ep-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  opacity: .3;
}

.editorial-card-body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  flex: 1;
}

.editorial-tag {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  background: var(--color-accent-light);
  color: var(--color-accent);
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
  padding: .2rem .6rem;
  border-radius: var(--radius-pill);
}

.editorial-title {
  font-size: 1.0625rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-text);
}
.editorial-featured .editorial-title {
  font-size: clamp(1.125rem, 2vw, 1.375rem);
}

.editorial-excerpt {
  font-size: .875rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: .75rem;
  color: var(--color-text-muted);
  margin-top: auto;
  padding-top: .25rem;
}
.meta-sep { opacity: .4; }

.editorial-read-more {
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  margin-top: .25rem;
}
.editorial-read-more:hover { text-decoration: underline; }

.editorial-card.editorial-featured { grid-row: span 2; }

/* ===========================
   Newsletter
   =========================== */
.newsletter-section {
  background: var(--color-text);
  color: var(--color-text-inverse);
  padding-block: clamp(2.5rem, 6vw, 5rem);
}

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.newsletter-content h2 {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 800;
  letter-spacing: -.03em;
  margin-bottom: .75rem;
}

.newsletter-content p {
  font-size: 1rem;
  color: rgba(255,255,255,.7);
  max-width: 420px;
  line-height: 1.7;
}

.newsletter-perks {
  display: flex;
  gap: 1.5rem;
  margin-top: 1.25rem;
  flex-wrap: wrap;
}

.newsletter-perk {
  display: flex;
  align-items: center;
  gap: .375rem;
  font-size: .8125rem;
  color: rgba(255,255,255,.75);
}
.perk-icon { color: #4ade80; font-size: .875rem; }

.newsletter-form-group {
  display: flex;
  gap: .75rem;
  flex-wrap: wrap;
}

.newsletter-field {
  display: flex;
  flex-direction: column;
  gap: .375rem;
  flex: 1;
  min-width: 200px;
}

.newsletter-field label {
  font-size: .8125rem;
  font-weight: 500;
  color: rgba(255,255,255,.75);
}

.newsletter-field input {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.2);
  border-radius: var(--radius-md);
  padding: .75rem 1rem;
  font: inherit;
  font-size: .9375rem;
  color: #fff;
  outline: none;
