+  -webkit-overflow-scrolling: touch;
+}
+.category-list::-webkit-scrollbar { display: none; }
+
+.category-item {
+  flex-shrink: 0;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: .5rem;
+  cursor: pointer;
+}
+
+.category-item a {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: .5rem;
+  padding: .5rem .75rem;
+  border-radius: var(--radius-md);
+  transition: background var(--transition);
+}
+.category-item a:hover { background: var(--color-surface-alt); }
+
+.category-icon {
+  width: 56px; height: 56px;
+  background: var(--color-surface-alt);
+  border-radius: var(--radius-md);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 1.5rem;
+  transition: background var(--transition);
+}
+.category-item a:hover .category-icon { background: var(--color-accent-light); }
+
+.category-label {
+  font-size: .8125rem;
+  font-weight: 500;
+  color: var(--color-text-muted);
+  white-space: nowrap;
+}
+
+/* ===========================
+   Sections (shared spacing)
+   =========================== */
+.section { padding-block: clamp(2rem, 5vw, 4rem); }
+
+/* ===========================
+   Product grid
+   =========================== */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
+  gap: 1.5rem;
+}
+
+/* Product card */
+.product-card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  transition: box-shadow var(--transition), transform var(--transition);
+  display: flex;
+  flex-direction: column;
+}
+.product-card:hover {
+  box-shadow: var(--shadow-md);
+  transform: translateY(-2px);
+}
+
+.product-card-media {
+  position: relative;
+  aspect-ratio: 1;
+  background: var(--color-surface-alt);
+  overflow: hidden;
+}
+
+.product-card-img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+  transition: transform 300ms ease;
+}
+.product-card:hover .product-card-img { transform: scale(1.04); }
+
+/* Placeholder image */
+.product-img-placeholder {
+  width: 100%;
+  height: 100%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 3rem;
+}
+
+.product-badge {
+  position: absolute;
+  top: .75rem;
+  left: .75rem;
+  padding: .2rem .6rem;
+  border-radius: var(--radius-pill);
+  font-size: .7rem;
+  font-weight: 700;
+  letter-spacing: .04em;
+  text-transform: uppercase;
+}
+.badge-new { background: var(--color-badge-new); color: #fff; }
+.badge-sale { background: var(--color-accent); color: #fff; }
+.badge-bestseller { background: #78350f; color: #fef3c7; }
+
+.product-card-wishlist {
+  position: absolute;
+  top: .75rem;
+  right: .75rem;
+  width: 32px; height: 32px;
+  background: var(--color-surface);
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--color-text-muted);
+  box-shadow: var(--shadow-sm);
+  transition: color var(--transition), background var(--transition);
+}
+.product-card-wishlist:hover { color: var(--color-accent); background: var(--color-accent-light); }
+.product-card-wishlist[aria-pressed="true"] { color: var(--color-accent); }
+
+.product-card-body {
+  padding: 1rem;
+  display: flex;
+  flex-direction: column;
+  gap: .375rem;
+  flex: 1;
+}
+
+.product-brand {
+  font-size: .75rem;
+  font-weight: 600;
+  color: var(--color-text-muted);
+  text-transform: uppercase;
+  letter-spacing: .05em;
+}
+
+.product-name {
+  font-size: .9375rem;
+  font-weight: 600;
+  line-height: 1.35;
+  color: var(--color-text);
+}
+
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: .375rem;
+}
+.stars {
+  display: flex;
+  color: #f59e0b;
+  font-size: .8125rem;
+}
+.rating-count {
+  font-size: .75rem;
+  color: var(--color-text-muted);
+}
+
+.product-price-row {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  flex-wrap: wrap;
+  margin-top: auto;
+  padding-top: .25rem;
+}
+.price-current {
+  font-size: 1.0625rem;
+  font-weight: 700;
+  color: var(--color-text);
+}
+.price-original {
+  font-size: .875rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+.price-save {
+  font-size: .75rem;
+  font-weight: 600;
+  color: var(--color-deal);
+  background: var(--color-deal-bg);
+  padding: .1rem .4rem;
+  border-radius: var(--radius-pill);
+}
+
+.product-card-footer {
+  padding: 0 1rem 1rem;
+}
+
+.btn-add-cart {
+  width: 100%;
+  justify-content: center;
+  background: var(--color-text);
+  color: #fff;
+  padding: .625rem 1rem;
+  border-radius: var(--radius-md);
+  font-size: .875rem;
+  font-weight: 600;
+  transition: background var(--transition), transform var(--transition);
+}
+.btn-add-cart:hover { background: var(--color-accent); }
+.btn-add-cart:active { transform: scale(.97); }
+
+/* ===========================
+   Deals section
+   =========================== */
+.deals-section {
+  background: var(--color-surface);
+  border-top: 1px solid var(--color-border);
+  border-bottom: 1px solid var(--color-border);
+}
+
+.deals-header-inner {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  flex-wrap: wrap;
+  gap: 1rem;
+  margin-bottom: 1.75rem;
+}
+
+.deals-title-group {
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+}
+
+.deals-title-group h2 {
+  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
+  font-weight: 700;
+  letter-spacing: -.02em;
+}
+
+.countdown {
+  display: flex;
+  align-items: center;
+  gap: .375rem;
+  background: var(--color-accent-light);
+  border: 1px solid rgba(200,68,26,.2);
+  border-radius: var(--radius-pill);
+  padding: .3rem .875rem;
+}
+
+.countdown-label {
+  font-size: .75rem;
+  font-weight: 600;
+  color: var(--color-accent);
+  text-transform: uppercase;
+  letter-spacing: .05em;
+}
+
+.countdown-timer {
+  display: flex;
+  align-items: center;
+  gap: .125rem;
+  font-size: .875rem;
+  font-weight: 700;
+  color: var(--color-accent);
+  font-variant-numeric: tabular-nums;
+}
+
+.countdown-sep { opacity: .6; }
+
+/* Deal card — horizontal layout */
+.deal-card {
+  background: var(--color-bg);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  display: flex;
+  gap: 0;
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+.deal-card:hover {
+  box-shadow: var(--shadow-md);
+  transform: translateY(-2px);
+}
+
+.deal-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
+  gap: 1.25rem;
+}
+
+.deal-card-media {
+  width: 120px;
+  flex-shrink: 0;
+  background: var(--color-surface-alt);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 2.5rem;
+}
+
+.deal-card-body {
+  padding: 1.125rem;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+  gap: .375rem;
+}
+
+.deal-card-name {
+  font-size: .9375rem;
+  font-weight: 600;
+  line-height: 1.35;
+}
+
+.deal-card-original {
+  font-size: .8125rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+
+.deal-card-price {
+  font-size: 1.25rem;
+  font-weight: 800;
+  color: var(--color-accent);
+}
+
+.deal-progress {
+  display: flex;
+  flex-direction: column;
+  gap: .25rem;
+  margin-top: auto;
+}
+
+.progress-bar {
+  height: 6px;
+  background: var(--color-border);
+  border-radius: var(--radius-pill);
+  overflow: hidden;
+}
+
+.progress-fill {
+  height: 100%;
+  background: var(--color-deal);
+  border-radius: var(--radius-pill);
+  transition: width 1.2s ease;
+}
+
+.progress-label {
+  font-size: .75rem;
+  color: var(--color-text-muted);
+}
+.progress-label strong { color: var(--color-deal); }
+
+/* ===========================
+   Editorial section
+   =========================== */
+.editorial-section { background: var(--color-bg); }
+
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr;
+  grid-template-rows: auto auto;
+  gap: 1.5rem;
+}
+
+.editorial-card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+.editorial-card:hover {
+  box-shadow: var(--shadow-md);
+  transform: translateY(-2px);
+}
+
+.editorial-card-media {
+  aspect-ratio: 16/7;
+  background: var(--color-surface-alt);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  overflow: hidden;
+  position: relative;
+}
+.editorial-card:not(.editorial-featured) .editorial-card-media {
+  aspect-ratio: 16/9;
+}
+
+.editorial-placeholder {
+  width: 100%;
+  height: 100%;
+  display: flex;
+  align-items: flex-end;
+  padding: 1.5rem;
+  position: relative;
+}
+
+.ep-bg {
+  position: absolute;
+  inset: 0;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 4rem;
+  opacity: .3;
+}
+
+.editorial-card-body {
+  padding: 1.25rem;
+  display: flex;
+  flex-direction: column;
+  gap: .5rem;
+  flex: 1;
+}
+
+.editorial-tag {
+  display: inline-flex;
+  align-items: center;
+  width: fit-content;
+  background: var(--color-accent-light);
+  color: var(--color-accent);
+  font-size: .7rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  padding: .2rem .6rem;
+  border-radius: var(--radius-pill);
+}
+
+.editorial-title {
+  font-size: 1.0625rem;
+  font-weight: 700;
+  line-height: 1.3;
+  color: var(--color-text);
+}
+.editorial-featured .editorial-title {
+  font-size: clamp(1.125rem, 2vw, 1.375rem);
+}
+
+.editorial-excerpt {
+  font-size: .875rem;
+  color: var(--color-text-muted);
+  line-height: 1.6;
+  display: -webkit-box;
+  -webkit-line-clamp: 3;
+  -webkit-box-orient: vertical;
+  overflow: hidden;
+}
+
+.editorial-meta {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  font-size: .75rem;
+  color: var(--color-text-muted);
+  margin-top: auto;
+  padding-top: .25rem;
+}
+.meta-sep { opacity: .4; }
+
+.editorial-read-more {
+  display: inline-flex;
+  align-items: center;
+  gap: .375rem;
+  font-size: .875rem;
+  font-weight: 600;
+  color: var(--color-accent);
+  margin-top: .25rem;
+}
+.editorial-read-more:hover { text-decoration: underline; }
+
+.editorial-card.editorial-featured { grid-row: span 2; }
+
+/* ===========================
+   Newsletter
+   =========================== */
+.newsletter-section {
+  background: var(--color-text);
+  color: var(--color-text-inverse);
+  padding-block: clamp(2.5rem, 6vw, 5rem);
+}
+
+.newsletter-inner {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 3rem;
+  align-items: center;
+}
+
+.newsletter-content h2 {
+  font-size: clamp(1.5rem, 3vw, 2.25rem);
+  font-weight: 800;
+  letter-spacing: -.03em;
+  margin-bottom: .75rem;
+}
+
+.newsletter-content p {
+  font-size: 1rem;
+  color: rgba(255,255,255,.7);
+  max-width: 420px;
+  line-height: 1.7;
+}
+
+.newsletter-perks {
+  display: flex;
+  gap: 1.5rem;
+  margin-top: 1.25rem;
+  flex-wrap: wrap;
+}
+
+.newsletter-perk {
+  display: flex;
+  align-items: center;
+  gap: .375rem;
+  font-size: .8125rem;
+  color: rgba(255,255,255,.75);
+}
+.perk-icon { color: #4ade80; font-size: .875rem; }
+
+.newsletter-form-group {
+  display: flex;
+  gap: .75rem;
+  flex-wrap: wrap;
+}
+
+.newsletter-field {
+  display: flex;
+  flex-direction: column;
+  gap: .375rem;
+  flex: 1;
+  min-width: 200px;
+}
+
+.newsletter-field label {
+  font-size: .8125rem;
+  font-weight: 500;
+  color: rgba(255,255,255,.75);
+}
+
+.newsletter-field input {
+  background: rgba(255,255,255,.08);
+  border: 1px solid rgba(255,255,255,.2);
+  border-radius: var(--radius-md);
+  padding: .75rem 1rem;
+  font: inherit;
+  font-size: .9375rem;
+  color: #fff;
+  outline: none;
+  transition: border-color var(--transition), box-shadow var(--transition);
+}
+.newsletter-field input::placeholder { color: rgba(255,255,255,.4); }
+.newsletter-field input:focus {
+  border-color: rgba(255,255,255,.5);
+  box-shadow: 0 0 0 3px rgba(255,255,255,.1);
+}
+
+.newsletter-field input[aria-invalid="true"] {
+  border-color: #f87171;
+}
+
+.newsletter-form-error {
+  font-size: .75rem;
+  color: #fca5a5;
+  min-height: 1rem;
+}
+
+.newsletter-submit {
+  align-self: flex-end;
+  background: var(--color-accent);
+  color: #fff;
+  padding: .75rem 1.5rem;
+  border-radius: var(--radius-md);
+  font-size: .9375rem;
+  font-weight: 600;
+  transition: background var(--transition), transform var(--transition);
+  white-space: nowrap;
+  height: fit-content;
+}
+.newsletter-submit:hover { background: var(--color-accent-hover); }
+.newsletter-submit:active { transform: scale(.97); }
+.newsletter-submit:focus-visible {
+  outline: 2px solid #fff;
+  outline-offset: 2px;
+}
+
+.newsletter-success {
+  display: none;
+  align-items: center;
+  gap: .75rem;
+  background: rgba(74,222,128,.1);
+  border: 1px solid rgba(74,222,128,.3);
+  border-radius: var(--radius-md);
+  padding: .875rem 1rem;
+  color: #4ade80;
+  font-weight: 600;
+}
+.newsletter-success.visible { display: flex; }
+
+/* ===========================
+   Trust bar
+   =========================== */
+.trust-bar {
+  background: var(--color-surface);
+  border-bottom: 1px solid var(--color-border);
+  padding-block: 1.25rem;
+}
+
+.trust-list {
+  display: flex;
+  gap: 1.5rem;
+  justify-content: center;
+  flex-wrap: wrap;
+}
+
+.trust-item {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  font-size: .875rem;
+  color: var(--color-text-muted);
+}
+.trust-icon { font-size: 1.125rem; }
+.trust-item strong { color: var(--color-text); font-weight: 600; }
+
+/* ===========================
+   Site footer
+   =========================== */
+.site-footer {
+  background: #141412;
+  color: rgba(255,255,255,.65);
+  padding-block: clamp(2rem, 5vw, 4rem) 1.5rem;
+}
+
+.footer-grid {
+  display: grid;
+  grid-template-columns: 2fr repeat(3, 1fr);
+  gap: 3rem;
+  padding-bottom: 3rem;
+  border-bottom: 1px solid rgba(255,255,255,.08);
+  margin-bottom: 2rem;
+}
+
+.footer-brand .site-logo { color: #fff; margin-bottom: 1rem; }
+
+.footer-desc {
+  font-size: .875rem;
+  line-height: 1.7;
+  max-width: 280px;
+  margin-bottom: 1.25rem;
+}
+
+.footer-social {
+  display: flex;
+  gap: .5rem;
+}
+.social-link {
+  width: 36px; height: 36px;
+  background: rgba(255,255,255,.08);
+  border-radius: var(--radius-sm);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: rgba(255,255,255,.65);
+  font-size: .875rem;
+  transition: background var(--transition), color var(--transition);
+}
+.social-link:hover { background: var(--color-accent); color: #fff; }
+
+.footer-col h3 {
+  font-size: .875rem;
+  font-weight: 700;
+  color: #fff;
+  margin-bottom: .875rem;
+  text-transform: uppercase;
+  letter-spacing: .05em;
+}
+
+.footer-links { display: flex; flex-direction: column; gap: .5rem; }
+.footer-links a {
+  font-size: .875rem;
+  color: rgba(255,255,255,.55);
+  transition: color var(--transition);
+  display: inline-block;
+}
+.footer-links a:hover { color: #fff; }
+
+.footer-bottom {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  flex-wrap: wrap;
+  gap: 1rem;
+  font-size: .8125rem;
+}
+
+.footer-legal {
+  display: flex;
+  gap: 1.5rem;
+  flex-wrap: wrap;
+}
+
+.footer-legal a { color: rgba(255,255,255,.45); }
+.footer-legal a:hover { color: rgba(255,255,255,.8); }
+
+/* ===========================
+   Live region
+   =========================== */
+.live-region {
+  position: absolute;
+  width: 1px; height: 1px;
+  overflow: hidden;
+  clip: rect(0,0,0,0);
+  white-space: nowrap;
+}
+
+/* ===========================
+   Toast notification
+   =========================== */
+.toast-container {
+  position: fixed;
+  bottom: 1.5rem;
+  right: 1.5rem;
+  z-index: 200;
+  display: flex;
+  flex-direction: column;
+  gap: .5rem;
+  max-width: 320px;
+}
+
+.toast {
+  background: var(--color-text);
+  color: #fff;
+  padding: .875rem 1.125rem;
+  border-radius: var(--radius-md);
+  font-size: .875rem;
+  font-weight: 500;
+  display: flex;
+  align-items: center;
+  gap: .625rem;
+  box-shadow: var(--shadow-lg);
+  animation: toastIn 200ms ease, toastOut 300ms ease 2.5s forwards;
+}
+
+.toast-icon { font-size: 1.125rem; flex-shrink: 0; }
+
+@keyframes toastIn {
+  from { opacity: 0; transform: translateX(1rem); }
+  to   { opacity: 1; transform: translateX(0); }
+}
+@keyframes toastOut {
+  from { opacity: 1; }
+  to   { opacity: 0; pointer-events: none; }
+}
+
+/* ===========================
+   Responsive
+   =========================== */
+@media (max-width: 1024px) {
+  .editorial-grid {
+    grid-template-columns: 1fr 1fr;
+  }
+  .editorial-card.editorial-featured { grid-row: span 1; }
+  .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
+}
+
+@media (max-width: 768px) {
+  .header-inner { grid-template-columns: auto 1fr auto; }
+  .primary-nav { display: none; }
+  .search-form { display: none; }
+  .menu-toggle { display: flex; }
+
+  .hero-inner { grid-template-columns: 1fr; min-height: auto; }
+  .hero-visual { display: none; }
+  .hero-badge { display: none; }
+
+  .editorial-grid { grid-template-columns: 1fr; }
+  .newsletter-inner { grid-template-columns: 1fr; gap: 2rem; }
+
+  .footer-grid { grid-template-columns: 1fr 1fr; }
+}
+
+@media (max-width: 480px) {
+  .deal-card-media { width: 90px; }
+  .footer-grid { grid-template-columns: 1fr; gap: 1.5rem; }
+  .footer-bottom { flex-direction: column; align-items: flex-start; }
+  .trust-list { flex-direction: column; align-items: flex-start; gap: .875rem; }
+}
+
+/* ===========================
+   Reduced motion
+   =========================== */
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after {
+    animation-duration: .01ms !important;
+    transition-duration: .01ms !important;
+    scroll-behavior: auto !important;
+  }
+}
+
+/* ===========================
+   Forced colors
+   =========================== */
+@media (forced-colors: active) {
+  .product-card,
+  .deal-card,
+  .editorial-card {
+    border: 1px solid ButtonText;
+  }
+  .btn-primary,
+  .btn-add-cart,
+  .newsletter-submit {
+    background: ButtonText;
+    color: ButtonFace;
+    forced-color-adjust: none;
+  }
+  .progress-fill { background: ButtonText; }
+  .cart-badge { background: ButtonText; color: ButtonFace; }
+  .hero-badge { background: ButtonText; color: ButtonFace; forced-color-adjust: none; }
+  :focus-visible { outline: 2px solid ButtonText; }
+}
+
